function previewModal(m){const url='/media.php?id='+m.id;showModal(t('preview')+' · '+m.name,`<div style="text-align:center">${m.kind==='audio'?`<div class="audio-preview-card">♫ <audio controls preload="metadata" src="${url}"></audio></div>`:m.kind==='stream'?`<div class="notice">Transmisión online · ${esc(m.mime==='video/mp4'?'MP4':'HLS sujeto a compatibilidad')}<p class="caption">${esc(m.stream_url||'')}</p></div><video class="preview-modal" controls playsinline src="${attr(m.stream_url||url)}"></video>`:m.mime?.startsWith('video/')?`<video class="preview-modal" controls autoplay playsinline src="${url}"></video>`:`<img class="preview-modal" src="${url}" alt="${attr(m.name)}">`}</div><p class="caption">${esc(m.name)} · ${m.kind==='stream'?'Conexión necesaria':size(m.bytes)}</p>`)}
