function spokenPosterModal(){
 const choices=state.playlists.map(pl=>[String(pl.id),pl.name]);
 showModal('Crear cartel con bot lector',`<form class="form-stack"><p class="notice">Escribe el mensaje del cartel. El sistema crea la imagen y el reproductor lee la narración cuando llegue su turno. No necesitas editar videos.</p><label>Texto grande del cartel<input class="field" name="title" maxlength="90" required placeholder="¡Hoy tenemos grandes ofertas!"></label><label>Texto secundario<input class="field" name="subtitle" maxlength="140" placeholder="Pregunta por nuestras promociones"></label><label>Lo que debe decir el bot<textarea class="field" name="voice_text" rows="4" maxlength="750" placeholder="Si lo dejas vacío, leerá el título y subtítulo."></textarea></label><div class="form-grid"><label>Estilo<select class="field" name="palette">${opt([['navy','Azul profesional'],['emerald','Verde'],['sunset','Rosa / naranja'],['night','Negro elegante']])}</select></label><label>Idioma<select class="field" name="voice_lang">${opt([['es-PE','Español Perú'],['es-ES','Español España'],['en-US','Inglés'],['pt-BR','Portugués']])}</select></label></div><label>Agregar a la lista<select name="playlist_id" class="field"><option value="">${state.editorId?'Lista abierta':'Crear una lista de carteles narrados'}</option>${choices.map(([id,name])=>`<option value="${id}" ${Number(id)===state.editorId?'selected':''}>${esc(name)}</option>`).join('')}</select></label><button type="button" class="btn btn-small btn-outline" data-act="spokenPosterTest">▶ Escuchar antes de crear</button><p class="helper">Duración calculada según el texto. Se guardará como borrador; tú eliges cuándo publicar.</p></form>`,async()=>{
  const form=$('#modal-inner form'),p=formVals(),voiceText=(p.voice_text||[p.title,p.subtitle].filter(Boolean).join('. ')).trim();
  if(!p.title?.trim())return toast('Escribe el cartel',true);
  try{
   const r=await api('media.intro',{title:p.title,subtitle:p.subtitle,brand:'SECTOR SIGN',call_to_action:'DESCUBRE MÁS',palette:p.palette});
   let id=Number(p.playlist_id)||state.editorId||0;
   if(!id){const created=await api('playlists.create',{name:'Carteles narrados'});id=created.id;}
   const target=await apiGet('playlist.get',{id});const arr=target.items;
   const duration=Math.max(8,Math.min(180,Math.ceil(voiceText.split(/\s+/).length/2.15)+3));
   arr.push({id:r.id,duration,fit:'contain',transition:'fade',schedule:{},audio:{media_id:'',mode:'mix',volume:85,voice:{text:voiceText,lang:p.voice_lang||'es-PE',rate:1,enabled:true,caption:true}}});
   await api('playlist.save',{id,revision:Number(target.playlist.revision),soundtrack:target.soundtrack||{},items:arr});
   closeModal();state.editor=null;state.editorId=null;await navigate('playlists');await openEditor(id,true);toast('Cartel narrado listo: escucha la vista previa y publícalo.');
  }catch(e){handleError(e);}
 },'Crear cartel narrado');
}
function introModal(){showModal('Crear intro de marca',`<form class="form-stack"><label>Marca<input class="field" name="brand" maxlength="64" value="SECTOR SIGN"></label><label>Título principal<input class="field" name="title" required maxlength="90" placeholder="¡BIENVENIDOS!"></label><label>Subtítulo<input class="field" name="subtitle" maxlength="140" placeholder="Ofertas para toda la familia"></label><label>Mensaje final<input class="field" name="call_to_action" maxlength="70" value="DESCUBRE MÁS"></label><label>Estilo<select class="field" name="palette">${opt([['navy','Azul profesional'],['emerald','Verde'],['sunset','Rosa / naranja'],['night','Negro elegante']])}</select></label><p class="caption">Creará una imagen vectorial 16:9. Puedes insertarla al comienzo de cualquier lista y definir su duración.</p></form>`,async()=>{try{const r=await api('media.intro',formVals());closeModal();await navigate('media');toast('Intro creada. Agrégala a una lista.');}catch(e){handleError(e);}},'Crear intro');}
function streamModal(){showModal('Agregar transmisión online',`<div class="notice">Enlaza una transmisión HTTPS directa MP4 o HLS (.m3u8). HLS solo funciona en reproductores compatibles; no sirve para duplicar la pantalla de un teléfono. Necesita internet y no se guarda offline.</div><form class="form-stack" style="margin-top:12px"><label>Nombre<input class="field" name="name" required maxlength="190" placeholder="Canal de eventos"></label><label>URL HTTPS<input class="field" name="url" type="url" required placeholder="https://servidor.com/directo.m3u8"></label></form>`,async()=>{try{await api('media.stream',formVals());closeModal();await navigate('media');toast('Transmisión agregada; pruébala en el dispositivo de destino.');}catch(e){handleError(e);}},'Guardar transmisión');}
function groupMembersModal(group){const selected=new Set(state.screens.filter(s=>String(s.group_id)===String(group.id)).map(s=>s.id));showModal('Pantallas · '+group.name,`<p class="helper">Cuidado: cada pantalla puede estar en un solo grupo comercial. Al guardar se aplicará la selección completa.</p><div class="scroll-members">${state.screens.map(s=>`<label class="check-row"><input type="checkbox" name="group-member" value="${attr(s.id)}" ${selected.has(s.id)?'checked':''}><span>${esc(s.name)}<small> · ${esc(s.location_name||'Sin local')}${s.group_id&&String(s.group_id)!==String(group.id)?' · grupo: '+esc(s.group_name):''}</small></span></label>`).join('')||'Vincula pantallas primero.'}</div>`,async()=>{try{const ids=$$('#modal-inner [name="group-member"]:checked').map(x=>x.value);await api('groups.assign',{group_id:group.id,screens:ids});closeModal();await navigate('groups');toast('Grupo actualizado ('+ids.length+' pantallas)');}catch(e){handleError(e);}});}
function groupControlModal(group){const count=state.screens.filter(s=>String(s.group_id)===String(group.id)).length;showModal('Control remoto · '+group.name,`<div class="notice">Se enviará el comando a ${count} dispositivos; los desconectados lo recibirán al reconectarse.</div><div class="card-buttons" style="margin-top:18px">${[['pause','⏸ Pausar todas'],['resume','▶ Reanudar todas'],['reload','↻ Recargar apps'],['capture','▣ Pedir capturas']].map(([id,label])=>btn(label,'groupCommand',group.id,'btn-outline btn-small').replace('data-act="groupCommand"','data-act="groupCommand" data-cmd="'+id+'"')).join('')}</div>`);}
function wallModal(wall){const d=wall||{name:'Pasillo 1',rows:2,cols:2,mode:'mirror',screens:[]};showModal(wall?'Editar videowall':'Crear videowall',`<form id="wall-form" class="form-stack"><label>Nombre<input class="field" name="name" required maxlength="120" value="${attr(d.name)}"></label><div class="form-grid"><label>Filas<select name="rows" class="field" id="wall-rows">${opt([[1,'1'],[2,'2'],[3,'3'],[4,'4']],d.rows)}</select></label><label>Columnas<select name="cols" class="field" id="wall-cols">${opt([[1,'1'],[2,'2'],[3,'3'],[4,'4']],d.cols)}</select></label></div><label>Modo<select class="field" name="mode">${opt([['mirror','Espejo: todos reproducen lo mismo'],['span','Panorámico: dividir imagen']],d.mode)}</select></label><div class="notice">El orden de posiciones es de izquierda a derecha, empezando arriba. Para un muro panorámico de 2×2, prepara una imagen en relación de aspecto 32:9, si cada monitor es 16:9.</div><div id="wall-grid" class="wall-grid-edit"></div></form>`,async()=>{try{const values=formVals(),screens=$$('#wall-grid select').map(n=>n.value),rows=Number(values.rows),cols=Number(values.cols);if(!screens.length||screens.some(x=>!x))throw Error('Asigna una pantalla diferente a cada posición');await api('walls.save',{id:wall?.id,name:values.name,rows,cols,mode:values.mode,screens});closeModal();await navigate('walls');toast('Videowall configurado');}catch(e){handleError(e);}},'Guardar videowall');
 const draw=()=>{const n=Number($('#wall-rows').value)*Number($('#wall-cols').value),node=$('#wall-grid');const chosen=$$('#wall-grid select').map(x=>x.value);if(!chosen.length)chosen.push(...(d.screens||[]));node.style.gridTemplateColumns=`repeat(${Number($('#wall-cols').value)},minmax(0,1fr))`;node.innerHTML=Array.from({length:n},(_,i)=>`<label><span>Monitor ${i+1}</span><select class="field" aria-label="Pantalla ${i+1}"><option value="">Elegir...</option>${opt(state.screens.map(s=>[s.id,s.name]),chosen[i])}</select></label>`).join('');};
 $('#wall-rows').onchange=draw;$('#wall-cols').onchange=draw;draw();}
function itemTransferModal(index){if(state.editorDirty){toast('Guarda los cambios antes de transferir anuncios',true);return;}const targets=state.playlists.filter(x=>Number(x.id)!==Number(state.editor.id));if(!targets.length){toast('Primero crea otra lista',true);return;}const it=state.editorItems[index];showModal('Mover o copiar anuncio',`<div class="notice">${esc(it.name)} · Lista actual: ${esc(state.editor.name)}</div><form class="form-stack" style="margin-top:12px"><label>Lista destino<select class="field" name="target_id">${opt(targets.map(x=>[x.id,x.name]))}</select></label><label>Acción<select class="field" name="mode">${opt([['copy','Copiar (mantener aquí)'],['move','Mover (retirar de aquí)']])}</select></label></form>`,async()=>{const {target_id,mode}=formVals();const dest=targets.find(x=>String(x.id)===String(target_id));if(!dest)return;try{await api('playlists.transfer_item',{source_id:state.editor.id,target_id:dest.id,index,source_revision:Number(state.editor.revision),target_revision:Number(dest.revision),mode});closeModal();state.editorId=null;state.editor=null;await navigate('playlists');await openEditor(Number(dest.id),true);toast(mode==='move'?'Anuncio movido':'Anuncio copiado');}catch(e){handleError(e);}});}
function mobileMoreModal(){showModal('Secciones',`<div class="more-grid">${nav.filter(([id])=>isAdmin()||!['users','settings','backup','doctor'].includes(id)).map(([id,ico])=>btn(ico+' '+t(id),'navigate',id,'btn-outline btn-small')).join('')}</div>`);}
function versionInfo(){
 const release=state.release||appBuild;
 const updates=(release.changes||[]).slice(0,12).map(s=>`<li>${esc(s)}</li>`).join('');
 showModal(t('version')+' · Sector Sign',`<div class="release-info"><div class="version-big">v${esc(release.version||'?')}</div><p class="caption">${t('lastUpdate')}: ${esc(prettyReleaseDate(release.released_at))}</p><p><b>${t('releaseNotes')}</b></p><ul>${updates}</ul><p class="helper">Versión cargada en este dispositivo: v${esc(appBuild.version)}. El servidor puede tener una versión nueva si aún no recargaste el panel.</p><div class="section-actions">${btn('↻ '+t('checkUpdate'),'versionCheck','','btn-outline btn-small')}${state.updateAvailable?btn('⬆ Recargar panel','reloadNow','','btn-small'):''}</div></div>`);
}
let livePollTimer=null,livePollBusy=false,liveFailures=0;
function scheduleLivePoll(delayMs=8000){
 clearTimeout(livePollTimer);
 if(!state.user)return;
 livePollTimer=setTimeout(pollLive,delayMs);
}
function paintLiveStatus(){
 const node=$('#live-indicator');if(node){node.textContent=liveIndicator();node.className='live-indicator '+state.liveState;}
 const badge=$('.version-chip');if(badge)badge.textContent='v'+(state.release?.version||appBuild.version);
}
async function pollLive(){
 if(!state.user)return;
 if(livePollBusy){scheduleLivePoll(2500);return;}
 if(document.visibilityState==='hidden'){scheduleLivePoll(16000);return;}
 livePollBusy=true;
 try{
  const v=await api('system.release',undefined,'GET');
  state.release=v.release||appBuild;
  state.updateAvailable=state.release.version!==appBuild.version;
  if(state.page==='screens'||state.page==='overview'){
   const r=await api('screens.list',undefined,'GET');
   const previousIds=state.screens.map(x=>x.id).join(',');
   state.screens=r.items||[];
   if(state.page==='screens'){
    if(previousIds!==state.screens.map(x=>x.id).join(',')&&!$('#modal')?.open&&!$('#screen-search:focus'))renderPage();
    else state.screens.forEach(s=>{
     const card=$$( '[data-live-screen]' ).find(x=>x.dataset.liveScreen===s.id);
     if(!card)return;const deviceEl=card.querySelector('[data-live-device]');if(deviceEl)deviceEl.innerHTML=deviceSummary(s);
     const status=card.querySelector('[data-live-status]');if(status)status.innerHTML=screenStatus(s);
     const versions=card.querySelector('[data-live-versions]');if(versions)versions.textContent=`${t('assigned')}: v${s.assigned_version??'—'} · ${t('applied')}: v${s.applied_version??'—'}`;
     const last=card.querySelector('[data-live-contact]');if(last)last.textContent=`◷ ${t('lastUpdate')}: ${localDate(s.last_seen_at)}`;
    });
   }else{
    const d=await api('dashboard',undefined,'GET');state.dashboard=d;
    const values={screens:d.stats?.screens??0,online:d.stats?.online??0,media:d.stats?.media??0,playlists:d.stats?.playlists??0};
    for(const key of Object.keys(values)){const node=$(`[data-live-stat="${key}"] b`);if(node)node.textContent=values[key];}
    const items=$$('.activity-row .pill');items.forEach((node,i)=>{if(state.screens[i])node.outerHTML=screenStatus(state.screens[i]);});
   }
  }
  state.lastSync=new Date().toISOString();state.liveState='online';liveFailures=0;paintLiveStatus();
 }catch(error){
  liveFailures=Math.min(5,liveFailures+1);state.liveState='offline';paintLiveStatus();
 }finally{
  livePollBusy=false;
  scheduleLivePoll(liveFailures?Math.min(60000,8000*2**liveFailures):8000+Math.floor(Math.random()*1000));
 }
}
window.addEventListener('online',()=>{if(state.user)scheduleLivePoll(500)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user)scheduleLivePoll(500)});
async function handleAction(action,id,element){
 try{if(action.startsWith('program')){await programAction(action,id);return;}if(action==='deviceDetails'){deviceDetails(id);return;}switch(action){
  case 'navigate':if($('#modal').open)closeModal();await navigate(id);break;
  case 'versionInfo':versionInfo();break;
  case 'versionCheck':await pollLive();versionInfo();toast(state.updateAvailable?t('newRelease'):t('serverUpdate'));break;
  case 'reloadNow':location.reload();break;
  case 'theme':state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('ss-theme',state.theme);document.documentElement.dataset.theme=state.theme;renderPage();break;
  case 'refresh':await navigate(state.page);break;
  case 'logout':await api('auth.logout',{});state.user=null;clearTimeout(livePollTimer);renderLogin();break;
  case 'playerOpen':window.open('/player.php','_blank','noopener');break;
  case 'modalClose':closeModal();break;
  case 'upload':$('#file-upload')?.click();break;
  case 'introNew':introModal();break;
  case 'spokenPosterNew':spokenPosterModal();break;
  case 'spokenPosterTest':{const form=$('#modal-inner form');studioSpeak((form?.elements?.voice_text?.value||[form?.elements?.title?.value,form?.elements?.subtitle?.value].filter(Boolean).join('. ')),form?.elements?.voice_lang?.value||'es-PE',1);break;}
  case 'streamNew':streamModal();break;
  case 'soundtrackConfig':soundtrackModal();break;
  case 'studioPreview':studioPreview();break;
  case 'studioRestart':studioRun(0);break;
  case 'studioStop':stopStudio();if($('#studio-stage'))$('#studio-stage').textContent='Vista previa detenida';break;
  case 'testVoice':{const form=$('#modal-inner form');studioSpeak(form?.elements?.voice_text?.value||'',form?.elements?.voice_lang?.value||'es-PE',Number(form?.elements?.voice_rate?.value||1));break;}
  case 'mobileMore':mobileMoreModal();break;
  case 'groupMembers':groupMembersModal(state.groups.find(x=>String(x.id)===String(id)));break;
  case 'groupControl':groupControlModal(state.groups.find(x=>String(x.id)===String(id)));break;
  case 'groupCommand':{const r=await api('groups.command',{group_id:Number(id),command:element.dataset.cmd});toast('Comando enviado a '+r.devices+' pantallas');break;}
  case 'wallNew':wallModal();break;
  case 'wallEdit':wallModal(state.walls.find(x=>String(x.id)===String(id)));break;
  case 'wallDelete':if(confirm('¿Eliminar este videowall? Las campañas publicadas se mantendrán.')){await api('walls.delete',{id:Number(id)});await navigate('walls');}break;
  case 'itemTransfer':itemTransferModal(Number(id));break;
  case 'screenPair':await Promise.all(['screens.list','locations.list','groups.list'].map(async a=>{const r=await api(a,undefined,'GET');state[a.split('.')[0]]=r.items;}));screenModal();break;
  case 'screenEdit':screenEditModal(state.screens.find(s=>s.id===id));break;
  case 'screenCommands':screenCommandsModal(state.screens.find(s=>s.id===id));break;
  case 'screenCapture':await api('screens.command',{id,command:'capture'});toast('Captura solicitada: aparecerá cuando el reproductor la entregue');break;
  case 'sendCommand':await api('screens.command',{id,command:element.dataset.cmd});toast('Orden enviada al dispositivo');break;
  case 'screenUnpair':if(confirm('¿Desvincular la pantalla? Tendrás que registrarla de nuevo.')){await api('screens.unpair',{id});closeModal();await navigate('screens');}break;
  case 'mediaPreview':previewModal(state.media.find(m=>m.id===id));break;
  case 'mediaDelete':if(confirm('¿Eliminar este archivo de la biblioteca?')){await api('media.delete',{id});await navigate('media');toast('Archivo archivado');}break;
  case 'listNew':showModal('Nueva lista',`<form class="form-stack"><label>Nombre<input name="name" class="field" required maxlength="160" placeholder="Promociones de fin de semana"></label></form>`,async()=>{try{let r=await api('playlists.create',formVals());closeModal();await navigate('playlists');await openEditor(r.id,true);}catch(e){handleError(e)}});break;
  case 'listOpen':await openEditor(id,true);break;
  case 'itemAdd':{
   let m=state.media.find(x=>x.id===id);if(!m)return;if(m.kind==='audio'){toast('Usa Configurar música o las opciones de un anuncio para agregar esta pista');return;}
   state.editorItems.push({id:m.id,name:m.name,mime:m.mime,sha256:m.sha256,bytes:Number(m.bytes),duration:8,transition:'fade',fit:'contain',schedule:{}});state.editorDirty=true;state.editorTab='list';refreshEditor();break;
  }
  case 'itemUp':moveItem(Number(id),Number(id)-1);break;
  case 'itemDown':moveItem(Number(id),Number(id)+1);break;
  case 'itemOptions':itemOptions(Number(id));break;
  case 'itemDuplicate':{let it=state.editorItems[Number(id)];state.editorItems.splice(Number(id)+1,0,structuredClone(it));state.editorDirty=true;closeModal();refreshEditor();break;}
  case 'itemDelete':state.editorItems.splice(Number(id),1);state.editorDirty=true;closeModal();refreshEditor();break;
  case 'editorTab':state.editorTab=id;refreshEditor();break;
  case 'listSave':{const r=await api('playlist.save',{id:state.editor.id,revision:Number(state.editor.revision),items:state.editorItems,soundtrack:state.soundtrack});state.editor.revision=r.revision;state.editorDirty=false;toast('Borrador guardado');await navigate('playlists');break;}
  case 'listPublish':publishModal();break;
  case 'listDuplicate':{const r=await api('playlists.duplicate',{id:Number(id)});state.editorId=null;state.editor=null;await navigate('playlists');await openEditor(r.id,true);toast('Lista duplicada');break;}
  case 'locationNew':promptCreate('locations');break;
  case 'groupNew':promptCreate('groups');break;
  case 'integrationNew':createIntegrationModal();break;
  case 'userInvite':inviteModal();break;
  case 'userResetLink':{const r=await api('users.reset_link',{id:Number(id)});showModal('Recuperación segura',`<div class="notice">Vence en 60 minutos y funciona una sola vez. Comparte solamente por un canal privado.</div><input class="field mono" id="reset-link" readonly value="${attr(r.reset_url)}"><button data-act="copyReset" class="btn btn-small" style="margin-top:12px">Copiar enlace</button>`);break;}
  case 'copyReset':await navigator.clipboard.writeText($('#reset-link').value);toast('Enlace copiado');break;
  case 'userToggle':{
   const u=state.users.find(x=>String(x.id)===String(id));if(!u)return;
   if(confirm((u.enabled?'¿Suspender ':'¿Activar ')+u.email+'?')){await api('users.toggle',{id,enabled:!Number(u.enabled)});await navigate('users');}break;
  }
  case 'screensSelectLocation':$$('#publish-screens input[type="checkbox"]').forEach(x=>{const screen=state.screens.find(s=>s.id===x.value);x.checked=screen?.location_name===id;});break;
  case 'screensSelectGroup':$$('#publish-screens input[type="checkbox"]').forEach(x=>{const screen=state.screens.find(s=>s.id===x.value);x.checked=screen?.group_name===id;});break;
  case 'screensSelectAll':$$('#publish-screens input[type="checkbox"]').forEach(x=>x.checked=true);break;
  case 'screensSelectNone':$$('#publish-screens input[type="checkbox"]').forEach(x=>x.checked=false);break;
  case 'copyCreds':await navigator.clipboard.writeText(element.dataset.cred);toast('Credenciales copiadas');break;
  case 'copyInvite':await navigator.clipboard.writeText($('#invite-link').value);toast('Enlace copiado');break;
  default:break;
 }}catch(e){handleError(e)}
}
const $$=(query,root=document)=>Array.from(root.querySelectorAll(query));
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();handleAction(b.dataset.act,b.dataset.id||'',b);});
document.addEventListener('change',async e=>{
 const el=e.target;
 if(el.id==='language'){state.lang=el.value;localStorage.setItem('ss-lang',state.lang);document.documentElement.lang=state.lang;renderPage();return;}
 if(el.id==='storage-driver'){$('#s3-fields').style.display=el.value==='s3'?'grid':'none';$('#ftps-fields').style.display=el.value==='ftps'?'grid':'none';return;}
 if(el.type==='file'&&el.id==='file-upload'){await uploadFiles(Array.from(el.files));return;}
 if(el.dataset.duration!==undefined){let i=Number(el.dataset.duration),it=state.editorItems[i];if(it){it.duration=Math.max(2,Math.min(600,Number(el.value)||8));state.editorDirty=true;refreshEditor();}return;}
 if(el.dataset.integrationAuto){try{await api('integrations.update',{id:el.dataset.integrationAuto,enabled:true,auto_publish:el.checked});toast('Integración actualizada');}catch(ex){handleError(ex)}return;}
});
document.addEventListener('submit',async e=>{
 if(!['org-form','storage-form','password-form','backup-policy-form'].includes(e.target.id)&&!e.target.classList.contains('oauth-provider-form'))return;
 e.preventDefault();const id=e.target.id;const values=Object.fromEntries(new FormData(e.target));
 try{
   if(e.target.classList.contains('oauth-provider-form')){values.provider=e.target.dataset.provider;await api('settings.oauth',values);}
   if(id==='backup-policy-form')await api('settings.backup_policy',values);
   if(id==='org-form')await api('settings.organization',values);
   if(id==='storage-form')await api('settings.storage',values);
   if(id==='password-form')await api('users.password',values);
   toast('Cambios guardados');await navigate(id==='backup-policy-form'?'backup':'settings');
 }catch(ex){handleError(ex);}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target?.matches?.('.drop-zone[role=button]')){e.preventDefault();$('#file-upload')?.click();}});
document.addEventListener('dragstart',e=>{const fromList=e.target.closest('[data-kind="play-item"]');if(fromList){e.dataTransfer.setData('text/plain',fromList.dataset.index);e.dataTransfer.effectAllowed='move';return;}const media=e.target.closest('[data-kind="library-item"]');if(media){e.dataTransfer.setData('application/x-sector-media',media.dataset.mediaId);e.dataTransfer.setData('text/uri-list','sector-sign://media/'+media.dataset.mediaId);e.dataTransfer.effectAllowed='copy';}});
function fileDropRegion(target){return target?.closest?.('#media-drop-zone,#editor-drop-zone,.media-layout .library');}
document.addEventListener('dragover',e=>{if((e.dataTransfer?.types||[]).includes('Files')&&fileDropRegion(e.target)){e.preventDefault();fileDropRegion(e.target).classList.add('drag-active');return;}if(e.target.closest('[data-kind="play-item"],#play-items-drop'))e.preventDefault();});
document.addEventListener('dragleave',e=>{if(fileDropRegion(e.target))fileDropRegion(e.target).classList.remove('drag-active');});
document.addEventListener('drop',e=>{
 const zone=fileDropRegion(e.target);
 if(zone&&(e.dataTransfer?.files?.length)){e.preventDefault();zone.classList.remove('drag-active');uploadFiles(Array.from(e.dataTransfer.files));return;}
 const target=e.target.closest('[data-kind="play-item"],#play-items-drop');if(!target)return;
 e.preventDefault();const mediaId=e.dataTransfer.getData('application/x-sector-media');
 if(mediaId){const m=state.media.find(x=>x.id===mediaId);if(m&&state.editor){if(m.kind==='audio'){const targetIndex=target.dataset.index;if(targetIndex!==undefined&&state.editorItems[Number(targetIndex)])state.editorItems[Number(targetIndex)].audio={...(state.editorItems[Number(targetIndex)].audio||{}),media_id:mediaId,mode:'mix',volume:85};else state.soundtrack={media_id:mediaId,volume:35};state.editorDirty=true;refreshEditor();toast('Pista de audio vinculada');return;}state.editorItems.push({id:m.id,name:m.name,mime:m.mime,kind:m.kind,stream_url:m.stream_url,sha256:m.sha256,bytes:Number(m.bytes),duration:8,transition:'fade',fit:'contain',schedule:{}});state.editorDirty=true;refreshEditor();}return;}
 const source=e.dataTransfer.getData('text/plain');if(source==='')return;const i=Number(source);const j=target.dataset.index===undefined?state.editorItems.length-1:Number(target.dataset.index);if(Number.isInteger(i)&&Number.isInteger(j))moveItem(i,j);
});
bootstrap();
